async function loadAdminControl(){if(!state.session?.permissions?.admin)return;state.adminControl=await optionalApi('api/v1/admin/control',null);renderAdminControl()}
function bindAdminControls(){document.querySelectorAll('[data-run-process]').forEach(button=>button.onclick=()=>runAdminProcess(button.dataset.runProcess,button));document.querySelectorAll('[data-save-process]').forEach(button=>button.onclick=async()=>{const card=button.closest('[data-process]'),code=card.dataset.process;button.disabled=true;try{await api('api/v1/admin/control',{method:'PUT',body:JSON.stringify({processes:{[code]:{enabled:card.querySelector('[data-process-enabled]').checked,interval_minutes:Number(card.querySelector('[data-process-interval]').value)}}})});toast('Update schedule saved');await loadAdminControl()}catch(error){toast(error.message)}finally{button.disabled=false}});document.querySelectorAll('[data-recover-id]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api(`api/v1/admin/recover/${button.dataset.recoverKind}/${button.dataset.recoverId}`,{method:'POST',body:'{}'});toast('Recovery completed');await loadAdminControl()}catch(error){toast(error.message)}finally{button.disabled=false}});if($('adminRecoverySweep'))$('adminRecoverySweep').onclick=()=>runAdminProcess('full_refresh',$('adminRecoverySweep'))}
