function renderSocial(){const data=state.social;if(!data)return;const fb=data.facebook||{},ig=data.instagram||{};$('socialLights').innerHTML=`<div class="system-light ${fb.configured?'green':'amber'}"><i></i><span><b>Facebook</b><small>${fb.configured?'Connected':'Needs setup'}</small></span></div><div class="system-light ${ig.configured?'green':'amber'}"><i></i><span><b>Instagram</b><small>${ig.configured?'Connected':'Needs setup'}</small></span></div>`;for(const [id,rows,network] of [['facebookPosts',fb.posts,'Facebook'],['instagramPosts',ig.posts,'Instagram']]){const node=$(id),items=rows||[];node.classList.toggle('empty',!items.length);node.innerHTML=items.length?items.map(row=>socialPost(row,network)).join(''):`${network} is not connected or has no recent posts.`}}
