function updateTvRangeLabels(form){for(const name of ['tv_map_brightness_percent','tv_adsb_zoom_level','tv_ais_zoom_level','tv_weather_zoom_level','tv_adsb_target_size_percent','tv_ais_target_size_percent']){const input=form.elements[name],output=document.querySelector(`[data-output="${name}"]`);if(!input||!output)continue;const value=Number(input.value);output.textContent=name.includes('percent')?`${input.value}%`:name.includes('adsb')||name.includes('ais')?(value>0?`Zoom in +${value}`:value<0?`Zoom out ${value}`:'Fit'):input.value}}
