function intakeType(section=''){const text=String(section).toLowerCase();if(text.includes('lab'))return'lab';if(text.includes('treatment')||text.includes('spray'))return'treatment';if(text.includes('labor')||text.includes('hour'))return'labor';if(text.includes('olive'))return'olive';if(text.includes('harvest'))return'harvest';if(text.includes('cellar'))return'cellar';if(text.includes('observation')||text.includes('scout'))return'scouting';if(text.includes('issue')||text.includes('decision'))return'issue';if(text.includes('work'))return'activity';return'issue'}
function factText(value){if(value==null)return'';if(typeof value==='string')return value;if(Array.isArray(value))return value.map(factText).filter(Boolean).join(' · ');return Object.entries(value).map(([key,item])=>`${key.replaceAll('_',' ')}: ${factText(item)}`).join(' · ')}
function prepareIntakeReply(item,data){const reply=String(data.suggested_reply||'').trim(),source=String(item.source||'');if(!reply)return;const channel=source==='gmail'?'gmail':source==='whatsapp'?'whatsapp':source==='imessage'?'imessage':'';$('intakeDialog').close();if(!channel){navigator.clipboard?.writeText(reply);toast('Suggested reply copied');return}document.querySelector(`[data-communication="${channel}"]`)?.click();const form=$(channel==='gmail'?'gmailCompose':channel==='whatsapp'?'whatsappCompose':'imessageCompose');if(!form)return;if(channel==='gmail'){form.elements.recipients.value=item.sender_address||'';form.elements.subject.value='Re: '+String(item.title||'Vineyard message').replace(/^re:\s*/i,'');form.elements.body.value=reply}else if(channel==='whatsapp'){form.elements.group.value='';form.elements.recipient.value=item.sender_address||'';form.elements.body.value=reply}else{form.elements.recipient.value=item.sender_address||'';form.elements.body.value=reply}form.scrollIntoView({behavior:'smooth',block:'center'});form.elements.body.focus();toast('Reply prepared — check it, then send')}
async function openIntakeReview(id){try{const item=await api(`api/v1/intake/${id}`),data=item.extracted_data||{},facts=Array.isArray(data.facts)?data.facts:[],uncertainties=Array.isArray(data.uncertainties)?data.uncertainties:[],suggestions=Array.isArray(data.suggested_database_records)?data.suggested_database_records:[],reply=String(data.suggested_reply||'').trim();state.intakeDraft=suggestions;state.intakeItemId=id;$('intakeDialogTitle').textContent=item.title||item.original_filename||'Incoming information';$('intakeDetail').innerHTML=`<p>${esc(data.summary||item.ai_summary||'AI analysis ready for review.')}</p><div class="intake-facts">${facts.map(value=>`<div class="intake-fact">${esc(factText(value))}</div>`).join('')||'<div class="intake-fact">No explicit facts were extracted.</div>'}</div>${uncertainties.length?`<article class="panel muted-panel"><h3>Check before saving</h3><p>${uncertainties.map(value=>esc(factText(value))).join('<br>')}</p></article>`:''}${reply?`<article class="panel ai-reply-draft"><h3>Suggested reply</h3><p>${esc(reply)}</p><button type="button" id="prepareIntakeReply">Prepare reply</button><small>Nothing is sent until you check it and press Send.</small></article>`:''}<div class="section-title"><h2>Proposed records</h2></div><div class="intake-actions">${suggestions.map((record,index)=>{const section=record.destination_section||record.section||record.record_type||'issue';return`<button data-use-intake="${index}">Approve as ${esc(intakeType(section).replace('_',' '))}</button>`}).join('')||'<button data-use-intake="fallback">Approve as issue</button>'}</div><p class="safety-note">The suggested form opens prefilled. Check the highlighted facts, then press Save once.</p>`;$('intakeDialog').showModal();if($('prepareIntakeReply'))$('prepareIntakeReply').onclick=()=>prepareIntakeReply(item,data);document.querySelectorAll('[data-use-intake]').forEach(button=>button.onclick=()=>{const suggestion=button.dataset.useIntake==='fallback'?{section:'issue',fields:{issue_text:data.summary||item.ai_summary||item.title,notes:uncertainties.map(factText).join('\n')}}:suggestions[Number(button.dataset.useIntake)];$('intakeDialog').close();openEntry(intakeType(suggestion.destination_section||suggestion.section||suggestion.record_type),suggestion.fields||suggestion.values||{},id)})}catch(error){toast(error.message)}}
function renderLabHistory(){const rows=state.labHistory||[],node=$('labHistoryList');if(!node)return;node.classList.toggle('empty',!rows.length);node.innerHTML=rows.length?rows.map(row=>`<button class="history-row" data-lab-sample="${row.sample_id}"><span><b>${esc(row.sample_name)}</b><small>${esc(row.sample_type)} · ${esc(row.laboratory||'Laboratory not recorded')} · ${row.result_count} results</small><small>${esc(row.results_summary||'')}</small></span><time>${new Date(`${row.lab_date}T12:00:00`).toLocaleDateString()}</time></button>`).join(''):'No laboratory history.';document.querySelectorAll('[data-lab-sample]').forEach(button=>button.onclick=()=>openLabSample(button.dataset.labSample))}
function enhanceEnologistControls(review={}){const form=$('labReviewForm');if(!form)return;const actions=form.querySelector('.dialog-actions');actions.insertAdjacentHTML('beforebegin',`<div class="enologist-control"><div class="chart-heading"><div><p class="eyebrow dark">ENOLOGIST CONTROL</p><h3>Approval</h3></div><span id="enologistState">${review.approved_at?'Approved':'Awaiting decision'}</span></div><div class="field-row"><label class="field">Decision type<select name="decision_type"><option value="">Choose…</option><option value="monitor">Monitor</option><option value="cellar_action">Cellar action</option><option value="harvest_action">Harvest action</option><option value="release">Release / approve</option><option value="hold">Hold</option></select></label><label class="field">Approved by<input name="approved_by" value="${esc(review.approved_by||'')}"></label></div><label class="field">Approval date and time<input type="datetime-local" name="approved_at"></label><button type="button" id="markEnologistApproved">Mark enologist approved</button></div>`);if(review.decision_type)form.elements.decision_type.value=review.decision_type;if(review.approved_at)form.elements.approved_at.value=String(review.approved_at).slice(0,16);$('markEnologistApproved').onclick=()=>{form.elements.approved_by.value=form.elements.approved_by.value||state.session?.username||state.session?.user||'Enologist';form.elements.approved_at.value=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);form.elements.review_status.value='closed';form.elements.enologist_approval_required.checked=false;$('enologistState').textContent='Ready to save approval'}}
async function openLabSample(id){try{const detail=await api(`api/v1/labs/samples/${id}`),review=detail.review||{},comparison=new Map((detail.comparison||[]).map(row=>[row.result_id,row]));$('labDialogTitle').textContent=detail.sample.sample_name;$('labDetail').innerHTML=`<p class="safety-note">${esc(detail.sample.sample_type)} · ${detail.sample.lab_date?new Date(`${detail.sample.lab_date}T12:00:00`).toLocaleDateString():''} · ${esc(detail.sample.laboratory||'Laboratory not recorded')}</p>`+detail.results.map(result=>{const c=comparison.get(result.id)||{},range=c.target_min!=null||c.target_max!=null?`Target ${c.target_min??'—'}–${c.target_max??'—'} ${c.unit||''}`:'No approved target range';return`<div class="lab-result-row flag-${esc(c.comparison_flag||'normal')}"><div><b>${esc(result.analyte_name)}</b><small>${esc(range)}${c.source_reference?' · '+esc(c.source_reference):''}</small></div><strong>${esc(result.numeric_value??result.text_value??'—')} ${esc(result.unit||'')}<small>${esc(c.comparison_flag||'not compared')}</small></strong>${state.session?.permissions?.write?`<button data-edit-result="${result.id}" data-value="${esc(result.numeric_value??'')}" data-unit="${esc(result.unit||'')}">Correct</button>`:''}</div>`}).join('')+(state.session?.permissions?.write?`<form id="labReviewForm" class="panel lab-review-form"><h3>Decision and follow-up</h3><div class="field-row"><label class="field">Status<select name="review_status"><option value="reviewing">Reviewing</option><option value="decision_needed">Decision needed</option><option value="monitoring">Monitoring</option><option value="closed">Closed</option></select></label><label class="field">Owner<input name="owner_text" value="${esc(review.owner_text||'')}"></label></div><label class="field">Interpretation<textarea name="interpretation">${esc(review.interpretation||'')}</textarea></label><label class="field">Decision / next action<textarea name="decision_action">${esc(review.decision_action||'')}</textarea></label><div class="field-row"><label class="field">Next check<input type="datetime-local" name="next_check_at"></label><label class="field checkbox-field"><input type="checkbox" name="enologist_approval_required" ${review.enologist_approval_required!==0?'checked':''}> Enologist approval required</label></div><div class="dialog-actions"><button type="submit">Save review</button></div></form>`:'')+(detail.revisions.length?`<details><summary>Correction history (${detail.revisions.length})</summary>${detail.revisions.map(r=>`<p><b>${esc(r.changed_by)}</b> · ${new Date(r.changed_at).toLocaleString()}<br>${esc(r.reason)}</p>`).join('')}</details>`:'');if(review.review_status&&$('labReviewForm'))$('labReviewForm').elements.review_status.value=review.review_status;if(review.next_check_at&&$('labReviewForm'))$('labReviewForm').elements.next_check_at.value=String(review.next_check_at).slice(0,16);enhanceEnologistControls(review);$('labDialog').showModal();document.querySelectorAll('[data-edit-result]').forEach(button=>button.onclick=()=>correctLabResult(button,id));if($('labReviewForm'))$('labReviewForm').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.target),payload=Object.fromEntries(form.entries());payload.enologist_approval_required=event.target.elements.enologist_approval_required.checked;for(const key of Object.keys(payload))if(payload[key]==='')payload[key]=null;try{await api(`api/v1/labs/${id}/review`,{method:'POST',body:JSON.stringify(payload)});toast('Lab decision saved');$('labDialog').close();await loadAll()}catch(error){toast(error.message)}}}catch(error){toast(error.message)}}
async function correctLabResult(button,sampleId){const value=prompt('Correct numeric value',button.dataset.value);if(value===null)return;const unit=prompt('Unit',button.dataset.unit);if(unit===null)return;const reason=prompt('Why is this being corrected?');if(!reason)return toast('A correction reason is required');try{await api(`api/v1/labs/results/${button.dataset.editResult}`,{method:'PATCH',body:JSON.stringify({numeric_value:value===''?null:Number(value),unit,reason})});toast('Correction saved with audit history');await openLabSample(sampleId);await loadAll()}catch(error){toast(error.message)}}
function weatherSeries(measure){const groups={};for(const row of state.weatherComparison||[]){groups[row.weather_year]??=Array(12).fill(null);groups[row.weather_year][Number(row.weather_month)-1]=row[measure]==null?null:Number(row[measure])}const series=Object.entries(groups).sort(([a],[b])=>Number(a)-Number(b)).map(([name,values])=>({name,values})),average=Array.from({length:12},(_,month)=>{const values=series.map(item=>item.values[month]).filter(value=>value!=null&&Number.isFinite(value));return values.length?values.reduce((sum,value)=>sum+value,0)/values.length:null});return{series,average}}
function drawWeatherComparison(){const measure=$('weatherMeasure')?.value||'temp_avg_c',colors=['#8a713e','#4f7d5b','#a85343','#597da1','#8e6496','#c07b37','#527f83','#d4af37'],labels=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'],selected=weatherSeries(measure),rain=weatherSeries('rain_mm'),withAverage=[...selected.series,{name:'Average',values:selected.average}],rainWithAverage=[...rain.series,{name:'Average',values:rain.average}];$('weatherLegend').innerHTML=withAverage.map((s,i)=>`<span><i style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${colors[i%colors.length]};margin-right:4px"></i>${s.name}${i===selected.series.length-1?' · current':s.name==='Average'?' · average':''}</span>`).join('')||'<span>No historical weather months imported</span>';lineChart('weatherCompareChart',withAverage,colors,260,labels);if($('weatherRainLegend'))$('weatherRainLegend').innerHTML=rainWithAverage.map((s,i)=>`<span><i style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${colors[i%colors.length]};margin-right:4px"></i>${s.name}${s.name==='Average'?' · average':''}</span>`).join('')||'<span>No historical rainfall imported</span>';lineChart('weatherRainChart',rainWithAverage,colors,260,labels)}
