fields.treatment=()=>`${blockField()}<div class="field-row"><div class="field"><label>Date & time</label><input type="datetime-local" name="application_date" required value="${today()}T08:00"></div><div class="field"><label>Status</label><select name="status"><option value="planned">Planned</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></div></div><div class="field"><label>Purpose</label><input name="purpose" required></div><div class="field"><label>Product</label><select name="product_id">${choices(state.reference.products,'id','name','Choose if known')}</select></div><div class="field-row"><div class="field"><label>Dose</label><input type="number" step="0.001" name="dose_amount"></div><div class="field"><label>Dose unit</label><input name="dose_unit" placeholder="kg/ha, ml/L…"></div></div><details><summary>Completed-treatment checks</summary><div class="check-grid">${['agronomist_approved','label_legal_confirmed','phi_checked','rei_checked','weather_checked','ppe_confirmed','actual_details_confirmed'].map(name=>`<label><input type="checkbox" name="${name}"> ${name.replaceAll('_',' ')}</label>`).join('')}</div></details><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
