fields.cellar_lot=()=>`<div class="field-row"><div class="field"><label>Cellar lot code</label><input name="code" required placeholder="2026-GRC-C01"></div><div class="field"><label>Name</label><input name="name" required placeholder="Grecanico 2026"></div></div><div class="field-row"><div class="field"><label>Started</label><input type="datetime-local" name="started_at" value="${today()}T12:00"></div><div class="field"><label>Stage</label><select name="stage"><option value="must">Must</option><option value="fermentation">Fermentation</option><option value="malo">Malo</option><option value="aging">Aging</option><option value="bottled">Bottled</option><option value="closed">Closed</option></select></div></div><div class="field-row"><div class="field"><label>Fruit kg</label><input type="number" step="0.1" name="fruit_kg"></div><div class="field"><label>Initial liters</label><input type="number" step="0.1" name="initial_l"></div></div><details><summary>More details</summary><div class="field-row"><div class="field"><label>Harvest lot</label><input name="harvest_lot_reference"></div><div class="field"><label>Variety</label><input name="variety_summary"></div></div><div class="field"><label>Responsible</label><input name="responsible"></div></details><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
fields.blend_plan=()=>`<div class="field-row"><div class="field"><label>Blend code</label><input name="code" required placeholder="2026-BAIAMONTE"></div><div class="field"><label>Wine / blend name</label><input name="name" required placeholder="Baiamonte Rosso 2026"></div></div><div class="field"><label>Components and quantities</label><textarea name="components_text" required placeholder="Nerello Mascalese — 900 kg (60%)&#10;Nerello Cappuccio — 450 kg (30%)&#10;Grenache — 150 kg (10%)"></textarea><small>One variety per line. Include kg and percentage so the cellar has one clear instruction.</small></div><div class="field-row"><div class="field"><label>Total grapes planned (kg)</label><input type="number" step="0.1" min="0" name="target_grapes_kg"></div><div class="field"><label>Crate size (kg)</label><input type="number" step="0.1" min="1" name="crate_weight_kg" value="15"></div></div><div class="field-row"><div class="field"><label>Expected yield (L/kg)</label><input type="number" step="0.001" min="0" name="expected_yield_l_per_kg" placeholder="0.65"></div><div class="field"><label>Target wine (L)</label><input type="number" step="0.1" min="0" name="target_volume_l"></div><div class="field"><label>Target bottles</label><input type="number" step="1" min="0" name="planned_bottles"></div></div><div class="field-row"><div class="field"><label>Planned blend date</label><input type="date" name="planned_blend_date" value="${today()}"></div><div class="field"><label>Decision status</label><select name="decision_status"><option value="draft">Draft</option><option value="review">Enologist review</option><option value="approved">Approved</option><option value="completed">Completed</option></select></div></div><div class="field"><label>Target style / objective</label><textarea name="target_style" placeholder="Freshness, tannin, color, acidity, aging goal…"></textarea></div><div class="field-row"><div class="field"><label>Approved by</label><input name="approved_by"></div><div class="field"><label>Notes</label><textarea name="notes"></textarea></div></div>`;
fields.fermentation=()=>`<div class="field"><label>Cellar lot</label><select name="wine_lot_id">${choices(state.reference.wine_lots,'id','code','Choose lot')}</select></div><div class="field-row"><div class="field"><label>Date & time</label><input type="datetime-local" name="observed_at" required value="${today()}T12:00"></div><div class="field"><label>Temperature °C</label><input type="number" step="0.1" name="temp_c"></div></div><div class="field-row"><div class="field"><label>Density / SG</label><input type="number" step="0.0001" name="density_sg"></div><div class="field"><label>°Brix</label><input type="number" step="0.1" name="brix"></div><div class="field"><label>pH</label><input type="number" step="0.01" name="ph"></div></div><div class="field"><label>Observation or action</label><textarea name="sensory_observation"></textarea></div><details><summary>Addition or next check</summary><div class="field"><label>Addition / action</label><input name="addition_action"></div><div class="field-row"><div class="field"><label>Quantity</label><input type="number" step="0.001" name="quantity"></div><div class="field"><label>Unit</label><input name="unit"></div></div><div class="field"><label>Next check</label><input type="datetime-local" name="next_check_at"></div></details>`;
fields.equipment=()=>`<div class="field-row"><div class="field"><label>Date</label><input type="date" name="event_date" required value="${today()}"></div><div class="field"><label>Equipment</label><input name="asset_name" required placeholder="Sprayer, press, pump…"></div></div><div class="field-row"><div class="field"><label>Status before use</label><select name="pre_use_status"><option>Ready</option><option>Hold</option><option>Maintenance</option></select></div><div class="field"><label><input type="checkbox" name="released"> Clean and released</label></div></div><div class="field"><label>Cleaning or maintenance done</label><textarea name="maintenance_action"></textarea></div><details><summary>More details</summary><div class="field"><label>Sanitation method</label><input name="sanitation_method"></div><div class="field-row"><div class="field"><label>Released by</label><input name="released_by"></div><div class="field"><label>Next due</label><input type="date" name="next_due_date"></div></div></details><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
function blockField(){return `<div class="field"><label>Block</label><select name="block_id"><option value="">All / none</option>${(state.reference?.blocks||[]).map(b=>`<option value="${b.id}">${esc(b.code)} — ${esc(b.name)}</option>`).join('')}</select></div>`}function categoryField(){return `<div class="field"><label>Category</label><select name="category">${state.reference.categories.map(c=>`<option value="${c}">${c.replace('_',' ')}</option>`).join('')}</select></div>`}
function openEntry(type,draft=null,intakeId=null){state.entry=type;state.intakeItemId=intakeId;const titles={task:'Plan a task',activity:'Log work',harvest:'Add harvest lot',purchase:'Add purchase invoice',sale:'Add sales invoice',cash:'Record cash movement',cellar:'Cellar operation',cellar_lot:'Start cellar lot',blend_plan:'Plan a vintage blend',fermentation:'Fermentation check',equipment:'Equipment & sanitation',maturity:'Grape maturity sample',scouting:'Observation',phenology:'Growth stage',treatment:'Treatment record',lab:'Laboratory result',labor:'Labor hours',inventory:'Inventory count',olive:'Olive record',issue:'Issue or decision'},photoTypes=new Set(['activity','harvest','cellar','cellar_lot','blend_plan','fermentation','equipment','maturity','scouting','phenology','treatment','lab','labor','olive','issue']),labResults=type==='lab'&&Array.isArray(draft?.results)?draft.results.filter(item=>item&&typeof item==='object'):[];$('dialogTitle').textContent=titles[type]+(intakeId?' — review AI draft':'');$('formFields').innerHTML=fields[type]()+(!labResults.length?'':`<section class="suggested-results"><b>${labResults.length} extracted laboratory results</b>${labResults.map(item=>`<div><span>${esc(item.analyte_name||item.analyte_code||'Analyte')}</span><strong>${esc(item.numeric_value??item.text_value??'—')} ${esc(item.unit||'')}</strong></div>`).join('')}<input type="hidden" name="results_json" value="${esc(JSON.stringify(labResults))}"><small>All listed results will be saved together after this final check.</small></section>`)+(!photoTypes.has(type)?'':`<div class="field photo-field"><label>Photos or supporting document (optional)</label><input type="file" name="attachments" accept="image/*,.pdf" multiple><small>Add a field photo, screenshot, instruction, timesheet or report to this record.</small></div>`);const values=labResults.length?{...draft,...labResults[0]}:draft;if(values&&typeof values==='object')for(const[key,value]of Object.entries(values)){const control=$('entryForm').elements.namedItem(key);if(!control||value==null)continue;if(control.type==='checkbox')control.checked=Boolean(value);else if(control.tagName==='SELECT'&&![...control.options].some(option=>option.value===String(value)))continue;else control.value=Array.isArray(value)?value.join('\n'):String(value)}$('entryDialog').showModal()}
function closeEntry(){if($('entryDialog').open)$('entryDialog').close('cancel')}
async function saveEntry(event){event.preventDefault();const form=new FormData(event.target),attachments=form.getAll('attachments').filter(file=>file instanceof File&&file.size);form.delete('attachments');const payload=Object.fromEntries(form.entries());for(const box of event.target.querySelectorAll('input[type=checkbox]'))payload[box.name]=box.checked;for(const key of Object.keys(payload))if(payload[key]==='')payload[key]=null;['labor_hours','worker_count','weight_kg','gross_kg','tare_kg','crate_count','fruit_temp_c','babo','taxable_amount','vat_amount','withholding_tax','amount_in','amount_out','amount','temp_c','density_sg','brix','ph','ta_g_l','disease_pct','fruit_kg','initial_l','volume_l','target_grapes_kg','target_volume_l','planned_bottles','crate_weight_kg','expected_yield_l_per_kg','quantity','incidence_pct','percent_complete','dose_amount','total_used','phi_days','regular_hours','hourly_rate_eur','quantity_on_hand','olives_harvested_kg','oil_liters','numeric_value'].forEach(key=>{if(payload[key]!=null)payload[key]=Number(payload[key])});const routes={task:'tasks',activity:'activities',harvest:'harvest',purchase:'finance/documents',sale:'finance/documents',cash:'finance/cash',cellar:'quick-entry/cellar_operation',cellar_lot:'quick-entry/cellar_lot',blend_plan:'quick-entry/blend_plan',fermentation:'quick-entry/fermentation',equipment:'quick-entry/equipment_event',maturity:'quick-entry/maturity_sample',scouting:'quick-entry/scouting',phenology:'quick-entry/phenology',treatment:'quick-entry/treatment',labor:'quick-entry/labor',inventory:'quick-entry/inventory_count',olive:'quick-entry/olive',issue:'quick-entry/issue'},attachmentTypes={activity:'activity',harvest:'harvest',cellar:'cellar_operation',cellar_lot:'cellar_lot',blend_plan:'blend_plan',fermentation:'fermentation',equipment:'equipment_event',maturity:'maturity_sample',scouting:'scouting',phenology:'phenology',treatment:'treatment',lab:'lab_sample',labor:'labor',olive:'olive',issue:'issue'};if(state.entry==='lab'){let extracted=[];if(payload.results_json)try{extracted=JSON.parse(payload.results_json)}catch{}const rawResults=Array.isArray(extracted)&&extracted.length?extracted:[{analyte_code:payload.analyte_code,analyte_name:payload.analyte_name,numeric_value:payload.numeric_value,unit:payload.unit}];payload.results=rawResults.map(item=>{const name=String(item.analyte_name||item.analyte_code||'result').trim(),code=String(item.analyte_code||name).toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'').slice(0,80)||'result';return{analyte_code:code,analyte_name:name,numeric_value:numeric(item.numeric_value),text_value:item.text_value==null?null:String(item.text_value),unit:item.unit==null?null:String(item.unit)}});delete payload.results_json;delete payload.analyte_code;delete payload.analyte_name;delete payload.numeric_value;delete payload.unit;routes.lab='lab-samples'}try{const entryType=state.entry,intakeId=state.intakeItemId,saved=await api(`api/v1/${routes[entryType]}?year=${state.year}`,{method:'POST',body:JSON.stringify(payload)});for(const file of attachments){const data=new FormData();data.set('file',file);const response=await fetch(`api/v1/attachments/${attachmentTypes[entryType]}/${saved.id}`,{method:'POST',body:data});if(!response.ok)throw new Error((await response.json().catch(()=>({}))).detail||'Record saved, but a photo could not be attached')}if(intakeId&&attachmentTypes[entryType])await api(`api/v1/intake/${intakeId}/link`,{method:'POST',body:JSON.stringify({entity_type:attachmentTypes[entryType],entity_id:saved.id})});$('entryDialog').close();toast(intakeId?'AI draft reviewed and saved with its source':attachments.length?'Saved with photo evidence':'Saved');loadAll()}catch(error){toast(error.message)}}
async function submitWorkbookImport(commit){const form=$('workbookImportForm'),result=$('workbookImportResult'),data=new FormData(form);if(![...data.values()].some(value=>value instanceof File&&value.size)){toast('Choose at least one workbook');return}if(commit&&!confirm('Import these workbooks into MariaDB now? Continue only because the Home Assistant backup completed successfully.'))return;data.set('commit',commit?'true':'false');data.set('confirmation',commit?'BACKUP VERIFIED':'');result.hidden=false;result.classList.remove('error');result.textContent=commit?'Importing…':'Checking workbooks…';try{const response=await fetch('api/v1/admin/import-workbooks',{method:'POST',body:data});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.detail||`Import failed (${response.status})`);const lines=[commit?'Import completed.':'Check completed — no database rows changed.'];for(const [name,report] of Object.entries(payload.reports||{})){lines.push(`\n${name.replace('_',' & ')}`);for(const [key,value] of Object.entries(report.counts||{}))lines.push(`${key.replaceAll('_',' ')}: ${value}`);if((report.warnings||[]).length)lines.push(`Warnings: ${report.warnings.join('; ')}`)}result.textContent=lines.join('\n');if(commit)loadAll()}catch(error){result.classList.add('error');result.textContent=error.message}}
function setupAssistantVoice(){const listen=$('assistantListen'),speak=$('assistantSpeak'),form=$('assistantForm'),answer=$('assistantAnswer'),status=$('assistantVoiceStatus'),language=$('assistantLanguage'),Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!listen||!speak||!form||!answer)return;if(!Recognition){listen.disabled=true;status.textContent='Voice input is not supported by this browser; typing still works.'}else{const recognition=new Recognition();recognition.continuous=false;recognition.interimResults=false;listen.onclick=()=>{try{recognition.lang=language?.value==='it'?'it-IT':'en-US';recognition.start();listen.disabled=true;status.textContent=language?.value==='it'?'In ascolto…':'Listening…'}catch{status.textContent='The microphone is already listening.'}};recognition.onresult=event=>{form.elements.question.value=event.results[0][0].transcript;status.textContent=language?.value==='it'?'Domanda acquisita — controlla o premi Chiedi.':'Question captured — review it or press Ask.'};recognition.onerror=event=>{status.textContent=`Microphone: ${event.error||'not available'}`};recognition.onend=()=>{listen.disabled=false}}if(!('speechSynthesis' in window)){speak.disabled=true}else{speak.onclick=()=>{const text=answer.textContent.trim();if(!text)return;speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang=language?.value==='it'?'it-IT':'en-US';speechSynthesis.speak(utterance)}}new MutationObserver(()=>{speak.disabled=!answer.textContent.trim()}).observe(answer,{childList:true,subtree:true,characterData:true})}
async function assistantSubmit(event){event.preventDefault();const answer=$('assistantAnswer'),button=event.submitter,form=new FormData(event.target);button.disabled=true;answer.hidden=false;answer.textContent=$('assistantLanguage')?.value==='it'?'Analisi dei dati del vigneto…':'Reviewing current vineyard data…';try{const result=await api('api/v1/assistant/ask',{method:'POST',body:JSON.stringify({question:form.get('question'),language:$('assistantLanguage')?.value||'en'})});answer.textContent=result.configured?result.answer:result.message}catch(error){answer.textContent=error.message}finally{button.disabled=false}}
async function saveContextSuggestion(form,answer){return api('api/v1/assistant/suggestion',{method:'POST',body:JSON.stringify({question:form.elements.question.value,answer:answer.textContent,language:form.elements.language.value,focus:form.dataset.focus})})}
function setupContextAI(){document.querySelectorAll('.context-ai-form').forEach(form=>{const answer=form.querySelector('[data-ai-answer]'),status=form.querySelector('[data-ai-status]'),listen=form.querySelector('[data-ai-listen]'),speak=form.querySelector('[data-ai-speak]'),review=form.querySelector('[data-ai-review]'),language=form.elements.language,Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){listen.disabled=true;status.textContent='Voice input is not supported here; typing still works.'}else{const recognition=new Recognition();recognition.continuous=false;recognition.interimResults=false;listen.onclick=()=>{recognition.lang=language.value==='it'?'it-IT':'en-US';recognition.start();listen.disabled=true;status.textContent=language.value==='it'?'In ascolto…':'Listening…'};recognition.onresult=event=>{form.elements.question.value=event.results[0][0].transcript;status.textContent=language.value==='it'?'Domanda pronta per la revisione.':'Question ready for review.'};recognition.onerror=event=>{status.textContent=`Microphone: ${event.error||'not available'}`};recognition.onend=()=>{listen.disabled=false}}if(!('speechSynthesis'in window))speak.disabled=true;else speak.onclick=()=>{if(!answer.textContent.trim())return;speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(answer.textContent);utterance.lang=language.value==='it'?'it-IT':'en-US';speechSynthesis.speak(utterance)};if(review)review.onclick=async()=>{review.disabled=true;try{await api('api/v1/assistant/suggestion',{method:'POST',body:JSON.stringify({question:form.elements.question.value,answer:answer.textContent,language:language.value,focus:form.dataset.focus})});status.textContent='Suggestion added to the Review Inbox; no record was changed.';toast('AI suggestion ready for human review');await loadAll()}catch(error){status.textContent=error.message;review.disabled=false}};form.onsubmit=async event=>{event.preventDefault();const submit=form.querySelector('[type="submit"]');submit.disabled=true;if(review)review.disabled=true;answer.hidden=false;answer.textContent=language.value==='it'?'Analisi dei dati registrati…':'Reviewing recorded data…';try{const result=await api('api/v1/assistant/ask',{method:'POST',body:JSON.stringify({question:form.elements.question.value,language:language.value,focus:form.dataset.focus})});answer.textContent=result.configured?result.answer:result.message;speak.disabled=!answer.textContent.trim()||!('speechSynthesis'in window);if(review)review.disabled=!result.configured||!answer.textContent.trim()}catch(error){answer.textContent=error.message}finally{submit.disabled=false}}});document.querySelectorAll('[data-ai-prompt]').forEach(button=>button.onclick=()=>{const card=button.closest('.ai-focus-card'),form=card?.querySelector('.context-ai-form');if(form){form.elements.question.value=button.dataset.aiPrompt;form.elements.question.focus()}})}
document.querySelectorAll('.tabs button').forEach(button=>button.onclick=()=>{document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b===button));document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${button.dataset.view}`));if(button.dataset.view==='weather')setTimeout(()=>renderWeather(),0);if(button.dataset.view==='lab')setTimeout(()=>drawLabChart(),0);if(button.dataset.view==='finance')setTimeout(()=>drawFinanceChart(state.finance?.monthly||[]),0)});document.querySelectorAll('[data-open]').forEach(button=>button.onclick=()=>openEntry(button.dataset.open));document.querySelectorAll('[data-task-filter]').forEach(button=>button.onclick=()=>{state.taskFilter=button.dataset.taskFilter;document.querySelectorAll('[data-task-filter]').forEach(b=>b.classList.toggle('active',b===button));renderTasks()});document.querySelectorAll('[data-close-dialog]').forEach(button=>button.onclick=closeEntry);$('entryDialog')?.addEventListener('click',event=>{if(event.target===$('entryDialog'))closeEntry()});$('entryDialog')?.addEventListener('close',()=>{if($('entryForm'))$('entryForm').reset();if($('formFields'))$('formFields').replaceChildren();state.entry=null;state.intakeItemId=null});if($('entryForm'))$('entryForm').onsubmit=saveEntry;if($('refresh'))$('refresh').onclick=loadAll;if($('todayDate'))$('todayDate').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});document.querySelectorAll('[data-record]').forEach(button=>button.onclick=()=>openRecords(button.dataset.record));document.querySelectorAll('[data-close-record]').forEach(button=>button.onclick=()=>$('recordDialog').close());document.querySelectorAll('[data-close-lab]').forEach(button=>button.onclick=()=>$('labDialog').close());document.querySelectorAll('[data-close-parcel]').forEach(button=>button.onclick=()=>$('parcelDialog').close());if($('weatherMeasure'))$('weatherMeasure').onchange=drawWeatherComparison;if($('labSearch'))$('labSearch').oninput=()=>{const query=$('labSearch').value.trim().toLowerCase();document.querySelectorAll('[data-lab-sample]').forEach(node=>node.hidden=!node.textContent.toLowerCase().includes(query))};if($('intakeForm'))$('intakeForm').onsubmit=async event=>{event.preventDefault();const data=new FormData(event.target);try{const response=await fetch('api/v1/intake/upload',{method:'POST',body:data});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.detail||'Upload failed');toast('Uploaded to the review inbox');event.target.reset();await loadAll()}catch(error){toast(error.message)}};if($('assistantForm'))$('assistantForm').onsubmit=async event=>{event.preventDefault();const answer=$('assistantAnswer'),button=event.submitter;button.disabled=true;answer.hidden=false;answer.textContent='Reviewing current vineyard data…';try{const result=await api('api/v1/assistant/ask',{method:'POST',body:JSON.stringify({question:new FormData(event.target).get('question')})});answer.textContent=result.configured?result.answer:result.message}catch(error){answer.textContent=error.message}finally{button.disabled=false}};if($('weatherImportForm'))$('weatherImportForm').onsubmit=async event=>{event.preventDefault();const status=$('weatherImportStatus'),data=new FormData(event.target);status.textContent='Importing weather history…';try{const response=await fetch('api/v1/weather/import-history',{method:'POST',body:data});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.detail||'Weather import failed');status.textContent=`Imported ${payload.imported} daily records; ${payload.skipped} non-data rows skipped.`;event.target.reset();await loadAll()}catch(error){status.textContent=error.message}};if($('pullFatture'))$('pullFatture').onclick=async()=>{const button=$('pullFatture');button.disabled=true;$('fattureStatus').textContent='Pulling authoritative records…';try{const result=await api('api/v1/finance/fattureincloud/pull',{method:'POST',body:'{}'});$('fattureStatus').textContent=result.configured?`Updated: ${Object.values(result.counts).reduce((a,b)=>a+b,0)} records checked`:result.message;if(result.configured)await loadAll()}catch(error){$('fattureStatus').textContent=error.message}finally{button.disabled=false}};setupYears();loadAll();
document.querySelectorAll('.tabs button').forEach(button=>button.addEventListener('click',()=>{const view=button.dataset.view;if(view==='lab')setTimeout(()=>{drawLabChart();renderLabTrends()},0);if(view==='harvest')setTimeout(()=>renderGrapes(),0);if(view==='projections')setTimeout(()=>renderProjections(),0);if(view==='olives')setTimeout(()=>renderOlives(),0);if(view==='history')setTimeout(()=>renderHistory(),0);if(view==='admin')loadAdminControl()}));document.querySelectorAll('[data-jump]').forEach(button=>button.onclick=()=>document.querySelector(`.tabs button[data-view="${button.dataset.jump}"]`)?.click());
function setupSuggestionUpdates(){document.querySelectorAll('[data-ai-update]').forEach(update=>{const form=update.closest('.context-ai-form'),answer=form?.querySelector('[data-ai-answer]'),status=form?.querySelector('[data-ai-status]');if(!form||!answer)return;const sync=()=>{update.disabled=!answer.textContent.trim()||answer.hidden};new MutationObserver(sync).observe(answer,{childList:true,subtree:true,characterData:true,attributes:true});sync();update.onclick=async()=>{update.disabled=true;try{const result=await saveContextSuggestion(form,answer);status.textContent='Review the proposed update, edit it if needed, then choose Save.';toast('AI suggestion opened for review');await loadAll();await openIntakeReview(result.id)}catch(error){status.textContent=error.message;sync()}}})}
setupSuggestionUpdates();
function renderEtna(){const e=state.etna||{},activity=e.activity||{},active=Boolean(activity.active),hero=$('etnaHero');if(!hero)return;hero.className=`etna-hero ${active?'erupting':'monitoring'}`;$('etnaState').textContent=activity.label||'Checking official sources';$('etnaStateDetail').textContent=active?`Official activity notice since ${activity.since?new Date(activity.since).toLocaleString():'recently'}. Review the latest INGV notice.`:`Baiamonte sits on Etna's northern slopes · ${e.generated_at?'checked '+new Date(e.generated_at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}):'waiting for first update'}`;const ash=e.ash_advisory||{},events=e.seismic_events||[],maxMag=events.map(x=>Number(x.magnitude)).filter(Number.isFinite).sort((a,b)=>b-a)[0];$('etnaMetrics').innerHTML=`<article class="metric"><span>Activity</span><strong>${esc(active?'NOTICE':'Monitoring')}</strong><small>INGV communications</small></article><article class="metric"><span>Aviation code</span><strong>${esc(ash.aviation_colour_code||'Unknown')}</strong><small>${esc(ash.advisory_number||'Toulouse VAAC')}</small></article><article class="metric"><span>Ash movement</span><strong>${esc(ash.ash_direction||'Not reported')}</strong><small>${esc(ash.plume_top||'plume height unavailable')}</small></article><article class="metric"><span>12-hour outlook</span><strong>${esc(ash.no_ash_expected_12h?'No ash expected':ash.forecast?.['12h']?'Ash forecast':'Not reported')}</strong><small>${esc(ash.issued_at||'waiting for advisory')}</small></article>`;const cameras=e.webcams||[];$('etnaCameras').innerHTML=cameras.length?cameras.map(camera=>`<a class="etna-camera" href="${esc(camera.source_url)}" target="_blank" rel="noopener"><img src="${esc(camera.image_url)}?t=${Date.now()}" alt="INGV Etna ${esc(camera.name)} camera"><span><b>${esc(camera.name)}</b><small>${camera.available?'Official INGV image':'Unavailable'}</small></span></a>`).join(''):'<div class="empty">Waiting for INGV camera images.</div>';const notices=e.communications||[];$('etnaNotices').classList.toggle('empty',!notices.length);$('etnaNotices').innerHTML=notices.length?notices.slice(0,8).map(row=>`<a class="history-row ${/PRIMO COMUNICATO|NOTIFICA EVENTO/i.test(row.description)?'urgent':''}" href="${esc(row.url)}" target="_blank" rel="noopener"><span><b>${esc(row.description)}</b><small>INGV Osservatorio Etneo</small></span><time>${esc(String(row.sent_at).replace('T',' ').replace('Z',' UTC'))}</time></a>`).join(''):'No Etna communications are cached yet.';$('etnaSeismic').classList.toggle('empty',!events.length);$('etnaSeismic').innerHTML=events.length?events.slice(0,10).map(row=>`<div class="history-row"><span><b>M ${esc(row.magnitude??'—')} · ${esc(row.place||'Etna area')}</b><small>${row.depth_km==null?'Depth —':esc(row.depth_km)+' km depth'}</small></span><time>${esc(row.time?new Date(row.time).toLocaleDateString():'—')}</time></div>`).join(''):'No recent events returned by the Etna catalogue.';const sources=[['Latest VAAC advisory',ash.url],['Latest INGV bulletin',e.bulletin?.url],['Toulouse VAAC ash advisories',e.vaac?.url||e.sources?.vaac],['Civil Protection alert level',e.civil_protection?.url||e.sources?.civil_protection],['Smithsonian Global Volcanism Program',e.sources?.gvp],['INGV seismic service',e.sources?.seismic]].filter(x=>x[1]);$('etnaSources').innerHTML=(ash.eruption_details?`<div class="history-row urgent"><span><b>${esc(ash.eruption_details)}</b><small>${esc(ash.remarks||'Latest Toulouse VAAC advisory')}</small></span><time>${esc(ash.next_advisory||'VAAC')}</time></div>`:'')+sources.map(([name,url])=>`<a class="history-row" href="${esc(url)}" target="_blank" rel="noopener"><span><b>${esc(name)}</b><small>Open authoritative source</small></span><time>↗</time></a>`).join('')}
async function loadEtna(refresh=false){const button=$('refreshEtna');if(button)button.disabled=true;try{state.etna=await api(`api/v1/etna${refresh?'?refresh=true':''}`);renderEtna()}catch(error){toast(`Etna: ${error.message}`)}finally{if(button)button.disabled=false}}
if($('refreshEtna'))$('refreshEtna').onclick=()=>loadEtna(true);document.querySelector('[data-view="etna"]')?.addEventListener('click',()=>loadEtna(false));loadEtna(false);setInterval(()=>{if(!document.hidden&&document.querySelector('#view-etna.active'))loadEtna(false)},300000);
const requestedView=new URLSearchParams(location.search).get('view');if(requestedView)document.querySelector(`.tabs button[data-view="${CSS.escape(requestedView)}"]`)?.click();
bindCommunications();bindSocial();bindTvConfig();if($('alertFilter'))$('alertFilter').onchange=()=>{state.alertFilter=$('alertFilter').value;renderAlerts()};if($('intakeFilter'))$('intakeFilter').onchange=()=>{state.intakeFilter=$('intakeFilter').value;renderIntake()};document.querySelectorAll('.tabs button').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.view==='inbox'&&!state.communications)loadCommunications();if(button.dataset.view==='social'&&!state.social)loadSocial();if(button.dataset.view==='tv-config'&&!state.tvConfig)loadTvConfig()}));const activeView=document.querySelector('.tabs button.active')?.dataset.view;if(activeView==='inbox')loadCommunications();if(activeView==='social')loadSocial();if(activeView==='tv-config')loadTvConfig();
if($('checkWorkbooks'))$('checkWorkbooks').onclick=()=>submitWorkbookImport(false);if($('commitWorkbooks'))$('commitWorkbooks').onclick=()=>submitWorkbookImport(true);setupAssistantVoice();setupContextAI();if($('assistantForm'))$('assistantForm').onsubmit=assistantSubmit;if($('projectionMeasure'))$('projectionMeasure').onchange=renderProjections;if($('oliveMeasure'))$('oliveMeasure').onchange=renderOlives;if($('historyMeasure'))$('historyMeasure').onchange=renderHistory;if($('financeDocsFilter'))$('financeDocsFilter').onchange=renderFinance;document.querySelectorAll('[data-close-intake]').forEach(button=>button.onclick=()=>$('intakeDialog').close());if($('rejectIntake'))$('rejectIntake').onclick=async()=>{if(!state.intakeItemId)return $('intakeDialog').close();try{await api(`api/v1/intake/${state.intakeItemId}/review`,{method:'PATCH',body:JSON.stringify({review_status:'rejected'})});$('intakeDialog').close();toast('Incoming item rejected');await loadAll()}catch(error){toast(error.message)}};
function renderGrapeLots(){const g=state.grapes||{},harvest=g.harvest_lots||[],cellar=g.cellar_lots||[],hn=$('grapeHarvestLots'),cn=$('grapeCellarLots');if(hn){hn.classList.toggle('empty',!harvest.length);hn.innerHTML=harvest.length?harvest.map(row=>`<details class="treatment-row"><summary><span class="list-icon">🍇</span><span><b>${esc(row.variety_name)} · ${known(row.weight_kg,' kg')}</b><small>${esc(row.block_code||'Block not recorded')} · ${esc(row.destination||'Destination not recorded')} · ${esc(row.condition_grade||'condition not recorded')}</small></span><time>${new Date(row.harvested_at).toLocaleDateString()}</time></summary><div class="treatment-detail"><p><b>Crates:</b> ${known(row.crate_count)}${row.avg_crate_kg?' · '+fmt(row.avg_crate_kg)+' kg average':''}</p><p><b>Maturity:</b> °Babo ${known(row.babo)} · Brix ${known(row.brix)} · pH ${known(row.ph)} · TA ${known(row.ta_g_l,' g/L')}</p><p><b>Notes:</b> ${esc(row.notes||'None')}</p></div></details>`).join(''):`No detailed harvest lots for ${state.year}.`;}if(cn){cn.classList.toggle('empty',!cellar.length);cn.innerHTML=cellar.length?cellar.map(row=>`<details class="treatment-row"><summary><span class="list-icon">◇</span><span><b>${esc(row.code)} — ${esc(row.name)}</b><small>${esc(row.variety_summary||'Blend not recorded')} · ${esc(row.stage)} · ${esc(row.container_code||row.container_name||'container not recorded')}</small></span><time>${known(row.volume_l,' L')}</time></summary><div class="treatment-detail"><p><b>Blend / varieties:</b> ${esc(row.variety_summary||'Not recorded')}</p><p><b>Fruit and yield:</b> ${known(row.fruit_kg,' kg fruit')} · ${known(row.initial_l,' L initial')} · ${known(row.free_run_l,' L free run')} · ${known(row.press_l,' L press')} · ${known(row.loss_l,' L loss')}</p><p><b>Source harvest:</b> ${esc(row.harvest_lot_reference||'Not linked')} · <b>Responsible:</b> ${esc(row.responsible||'Not recorded')}</p><p><b>Notes:</b> ${esc(row.notes||'None')}</p></div></details>`).join(''):`No blend or cellar-lot details for ${state.year}.`;}}
function renderBlendPlans(){const g=state.grapes||{},plans=g.blend_plans||[],history=g.blend_history||[],node=$('grapeBlendPlans'),historyNode=$('grapeBlendHistory'),recommendations=$('harvestRecommendations');if(recommendations){const rows=(g.varieties||[]).filter(row=>row.harvest_recommendation?.recommended_pick_date);recommendations.classList.toggle('empty',!rows.length);recommendations.innerHTML=rows.length?rows.map(row=>{const r=row.harvest_recommendation;return `<div class="list-row"><span class="list-icon">◷</span><div><b>${esc(row.name)} — ${new Date(`${r.recommended_pick_date}T12:00:00`).toLocaleDateString()}</b><small>${esc((r.approval_status||'review').replaceAll('_',' '))} · ${esc(r.confidence||'low')} confidence</small><small>${(r.evidence||[]).map(esc).join(' · ')||'Manual plan only'}${r.weather_summary?' · '+esc(r.weather_summary):''}</small></div><time>Review</time></div>`}).join(''):'No harvest date can be recommended until a plan, forecast or maturity report is recorded.'}if(node){node.classList.toggle('empty',!plans.length);node.innerHTML=plans.length?plans.map(row=>{const crates=row.estimated_crates==null?'not estimated':`${fmt(row.estimated_crates)} × ${fmt(row.crate_weight_kg||15)} kg crates`,volume=row.estimated_volume_l==null?'volume not estimated':`${fmt(row.estimated_volume_l)} L estimated`;return `<details class="treatment-row" open><summary><span class="list-icon">◈</span><span><b>${esc(row.code)} — ${esc(row.name)}</b><small>${esc(row.decision_status||'draft')} · ${crates} · ${volume}</small></span><time>${row.planned_blend_date?new Date(`${row.planned_blend_date}T12:00:00`).toLocaleDateString():state.year}</time></summary><div class="treatment-detail"><p><b>Blend quantities:</b><br>${esc(row.components_text).replace(/\n/g,'<br>')}</p><p><b>Totals:</b> ${known(row.target_grapes_kg,' kg grapes')} · ${crates} · ${volume} · ${known(row.planned_bottles,' bottles')}</p><p><b>Target:</b> ${esc(row.target_style||'Not recorded')}</p><p><b>Approval:</b> ${esc(row.approved_by||'Pending')} · ${esc(row.decision_status||'draft')}</p><p><b>Notes:</b> ${esc(row.notes||'None')}</p></div></details>`}).join(''):`No blend plan for ${state.year}. Use “+ Blend plan” to add one with 15 kg crates.`}if(historyNode){historyNode.classList.toggle('empty',!history.length);historyNode.innerHTML=history.length?`<div class="trend-head"><b>Vintage / blend</b><b>Planned grapes</b><b>Planned wine</b><b>Recorded result</b><b>Status</b></div>${history.map(row=>`<div class="trend-row"><b>${row.vintage_year}<br><small>${esc(row.name||row.code)}</small></b><span>${known(row.target_grapes_kg,' kg')}<br><small>${row.target_grapes_kg&&row.crate_weight_kg?fmt(Number(row.target_grapes_kg)/Number(row.crate_weight_kg))+' crates':''}</small></span><span>${known(row.target_volume_l,' L')}<br><small>${known(row.planned_bottles,' bottles')}</small></span><span>${known(row.actual_grapes_kg,' kg')}<br><small>${known(row.actual_volume_l,' L')}</small></span><span>${esc(row.decision_status||'draft')}</span></div>`).join('')}`:'Prior blend numbers will appear here as plans and matching cellar lots are recorded.'}}
